{
        var der = PkixFixtures.ReadDer(fileName);
        var expected = PkixFixtures.LoadExpected().Certificates[fileName];

        var certificate = Certificate.Decode(new Asn1Reader(der, Asn1Encoding.Der));
        var tbs = certificate.TbsCertificate.Value;
        var spki = tbs.SubjectPublicKeyInfo.Value;
        var extensions = tbs.Extensions!.Value.Value;

        Assert.Equal(expected.Asn1Version, tbs.Version);
        Assert.Equal(Asn1Integer.FromInt32(expected.SerialNumber), tbs.SerialNumber);
        Assert.Equal(expected.SignatureAlgorithm, certificate.SignatureAlgorithm.Algorithm.ToString());
        Assert.Equal(expected.SignatureAlgorithm, tbs.Signature.Algorithm.ToString());
        Assert.Equal(expected.NotBeforeUtc, tbs.Validity.NotBefore.Value);
        Assert.Equal(expected.NotAfterUtc, tbs.Validity.NotAfter.Value);
        AssertDn(expected.Subject, tbs.Subject.Value);
        AssertDn(expected.Issuer, tbs.Issuer.Value);

        Assert.Equal(expected.SubjectPublicKeyAlgorithm, spki.Algorithm.Algorithm.ToString());
        if (expected.SubjectPublicKeyParametersNull)
        {
            Assert.NotNull(spki.Algorithm.Parameters);
            Assert.True(spki.Algorithm.TryDecodeParameters(
                AlgorithmIdentifierParametersBindings.Oid12840113549111, out Asn1Null _));
        }

        Assert.Equal(expected.SubjectPublicKeyUnusedBits, spki.SubjectPublicKey.UnusedBits);
        Assert.Equal(expected.SubjectPublicKeyByteLength, spki.SubjectPublicKey.Span.Length);
        Assert.Equal(expected.SignatureUnusedBits, certificate.Signature.UnusedBits);
        Assert.Equal(expected.SignatureByteLength, certificate.Signature.Span.Length);

        Assert.NotNull(tbs.Extensions);
        Assert.Equal(expected.ExtensionOids, extensions.Select(e => e.ExtnID.ToString()).ToList());
        foreach (var expectedExt in expected.Extensions)
        {
            var actual = PkixFixtures.RequireExtension(extensions, expectedExt.Oid);
            Assert.Equal(expectedExt.Critical, actual.Critical);
        }

        using (var bcl = new X509Certificate2(der))
        {
            Assert.Equal(expected.SerialNumber, int.Parse(bcl.SerialNumber, System.Globalization.NumberStyles.HexNumber));
            Assert.Equal(expected.NotBeforeUtc, bcl.NotBefore.ToUniversalTime());
            Assert.Equal(expected.NotAfterUtc, bcl.NotAfter.ToUniversalTime());
            Assert.Equal(expected.SignatureAlgorithm, bcl.SignatureAlgorithm.Value);
            Assert.Equal(expected.Asn1Version + 1, bcl.Version);
            Assert.Equal(expected.SubjectPublicKeyAlgorithm, bcl.PublicKey.Oid.Value);
            Assert.Equal(expected.SubjectPublicKeyByteLength, bcl.PublicKey.EncodedKeyValue.RawData.Length);
        }

        var writer = new Asn1Writer(Asn1Encoding.Der);
        certificate.Encode(writer);
        var encoded = writer.Encode();
        Assert.Equal(der, encoded);

        var again = Certificate.Decode(new Asn1Reader(encoded, Asn1Encoding.Der));
        Assert.Equal(certificate.SignatureAlgorithm.Algorithm, again.SignatureAlgorithm.Algorithm);
        Assert.Equal(tbs.SerialNumber, again.TbsCertificate.Value.SerialNumber);
        Assert.Equal(spki.SubjectPublicKey.Span.Length, again.TbsCertificate.Value.SubjectPublicKeyInfo.Value.SubjectPublicKey.Span.Length);
    }

{
        var der = PkixFixtures.ReadDer(fileName);
        var expectedCert = PkixFixtures.LoadExpected().Certificates[fileName];
        var certificate = Certificate.Decode(new Asn1Reader(der, Asn1Encoding.Der));
        Assert.NotNull(certificate.TbsCertificate.Value.Extensions);
        var extensions = certificate.TbsCertificate.Value.Extensions!.Value.Value;

        foreach (var expected in expectedCert.Extensions)
        {
            var extension = PkixFixtures.RequireExtension(extensions, expected.Oid);
            Assert.Equal(expected.Critical, extension.Critical);

            switch (expected.Oid)
            {
                case "2.5.29.14":
                    AssertSubjectKeyIdentifier(extension, expected);
                    break;
                case "2.5.29.15":
                    AssertKeyUsage(extension, expected);
                    break;
                case "2.5.29.19":
                    AssertBasicConstraints(extension, expected);
                    break;
                case "2.5.29.35":
                    AssertAuthorityKeyIdentifier(extension, expected);
                    break;
                case "2.5.29.32":
                    AssertCertificatePolicies(extension, expected);
                    break;
                case "2.5.29.30":
                    AssertNameConstraints(extension, expected);
                    break;
                case "2.5.29.17":
                    AssertSubjectAltName(extension, expected);
                    break;
                default:
                    throw new Xunit.Sdk.XunitException($"Unhandled extension OID {expected.Oid} in test.");
            }
        }
    }

{
        var der = PkixFixtures.ReadDer(fileName);
        var expectedCert = PkixFixtures.LoadExpected().Certificates[fileName];
        var certificate = Certificate.Decode(new Asn1Reader(der, Asn1Encoding.Der));
        var expected = expectedCert.Extensions.Single(e => e.Oid == "2.5.29.17");
        var extension = PkixFixtures.RequireExtension(certificate.TbsCertificate.Value.Extensions!.Value.Value, expected.Oid);
        AssertSubjectAltName(extension, expected);

        var writer = new Asn1Writer(Asn1Encoding.Der);
        certificate.Encode(writer);
        Assert.Equal(der, writer.Encode());
    }

{
        const string fileName = "GoodCACRL.crl";
        var der = PkixFixtures.ReadDer(fileName);
        var expected = PkixFixtures.LoadExpected().Crls[fileName];

        var crl = CertificateList.Decode(new Asn1Reader(der, Asn1Encoding.Der));
        var tbs = crl.TbsCertList;

        Assert.Equal(expected.Asn1Version, tbs.Version);
        Assert.Equal(expected.SignatureAlgorithm, crl.SignatureAlgorithm.Algorithm.ToString());
        Assert.Equal(expected.SignatureAlgorithm, tbs.Signature.Algorithm.ToString());
        Assert.Equal(expected.ThisUpdateUtc, tbs.ThisUpdate.Value);
        Assert.NotNull(tbs.NextUpdate);
        Assert.Equal(expected.NextUpdateUtc, tbs.NextUpdate!.Value);
        AssertDn(expected.Issuer, tbs.Issuer);
        Assert.Equal(expected.SignatureUnusedBits, crl.Signature.UnusedBits);
        Assert.Equal(expected.SignatureByteLength, crl.Signature.Span.Length);

        Assert.NotNull(tbs.RevokedCertificates);
        Assert.Equal(expected.RevokedCertificates.Count, tbs.RevokedCertificates!.Length);
        for (var i = 0; i < expected.RevokedCertificates.Count; i++)
        {
            var want = expected.RevokedCertificates[i];
            var got = tbs.RevokedCertificates[i];
            Assert.Equal(Asn1Integer.FromInt32(want.SerialNumber), got.UserCertificate);
            Assert.Equal(want.RevocationDateUtc, got.RevocationDate.Value);
            Assert.NotNull(got.CrlEntryExtensions);
            var reasonExt = PkixFixtures.RequireExtension(got.CrlEntryExtensions!, "2.5.29.21");
            Assert.False(reasonExt.Critical);
            var reason = (CRLReason)(int)PkixFixtures.ExtnValueReader(reasonExt).ReadEnumerated(Asn1Tag.Enumerated);
            Assert.Equal(PkixFixtures.ParseCrlReason(want.CrlReason!), reason);
            PkixFixtures.AssertExtnValueRoundTrip(reasonExt, writer =>
            {
                writer.WriteEnumerated(Asn1Tag.Enumerated, (int)reason);
            });
        }

        Assert.NotNull(tbs.CrlExtensions);
        Assert.Equal(expected.CrlExtensionOids, tbs.CrlExtensions!.Select(e => e.ExtnID.ToString()).ToList());
        foreach (var expectedExt in expected.CrlExtensions)
        {
            var extension = PkixFixtures.RequireExtension(tbs.CrlExtensions!, expectedExt.Oid);
            Assert.Equal(expectedExt.Critical, extension.Critical);
            if (expectedExt.Oid == "2.5.29.35")
            {
                var aki = AuthorityKeyIdentifier.Decode(PkixFixtures.ExtnValueReader(extension));
                Assert.Equal(expectedExt.AuthorityKeyIdentifierHex, PkixFixtures.ToHex(aki.KeyIdentifier!.Value.Span));
                PkixFixtures.AssertExtnValueRoundTrip(extension, aki.Encode);
            }
            else if (expectedExt.Oid == "2.5.29.20")
            {
                var number = PkixFixtures.ExtnValueReader(extension).ReadIntegerValue(Asn1Tag.Integer);
                Assert.Equal(expectedExt.CrlNumber, number.GetInt32());
                PkixFixtures.AssertExtnValueRoundTrip(extension, writer =>
                {
                    writer.WriteInteger(Asn1Tag.Integer, number);
                });
            }
        }

        var writer = new Asn1Writer(Asn1Encoding.Der);
        crl.Encode(writer);
        var encoded = writer.Encode();
        Assert.Equal(der, encoded);

        var again = CertificateList.Decode(new Asn1Reader(encoded, Asn1Encoding.Der));
        Assert.Equal(tbs.NextUpdate!.Value, again.TbsCertList.NextUpdate!.Value);
        Assert.Equal(
            tbs.RevokedCertificates!.Select(e => e.UserCertificate).ToList(),
            again.TbsCertList.RevokedCertificates!.Select(e => e.UserCertificate).ToList());
    }

{
        var cn = Asn1Oid.Parse("2.5.4.3");
        var ou = Asn1Oid.Parse("2.5.4.11");
        var unknown = Asn1Oid.Parse("1.2.3.4");
        var ouAva = new Asn1Kit.Pkix.AttributeTypeAndValue { Type = ou };
        ouAva.SetValue(Asn1Kit.Pkix.AttributeTypeAndValueValueBindings.AsString.DirectoryString10, " Root ");
        var cnAva = new Asn1Kit.Pkix.AttributeTypeAndValue { Type = cn };
        cnAva.SetValue(Asn1Kit.Pkix.AttributeTypeAndValueValueBindings.AsString.DirectoryString6, "Doe, Jane+Jr");
        var unknownAva = new Asn1Kit.Pkix.AttributeTypeAndValue
        {
            Type = unknown,
            Value = Asn1Any.FromValue("X", static (writer, value) =>
                writer.WriteString(Asn1Tag.PrintableString, value, Asn1StringForm.Printable))
        };
        var bench = new[]
        {
            new[] { ouAva },
            new[] { cnAva, unknownAva }
        };
        var modern = new[]
        {
            new[] { new Asn1Kit.Modern.PKIXCommonTypes2009.SingleAttribute
                { Type = ou, Value = Asn1Any.FromValue(" Root ", static (writer, value) => writer.WriteString(Asn1Tag.Utf8String, value, Asn1StringForm.Utf8)) } },
            new[]
            {
                new Asn1Kit.Modern.PKIXCommonTypes2009.SingleAttribute
                    { Type = cn, Value = Asn1Any.FromValue("Doe, Jane+Jr", static (writer, value) => writer.WriteString(Asn1Tag.Utf8String, value, Asn1StringForm.Utf8)) },
                new Asn1Kit.Modern.PKIXCommonTypes2009.SingleAttribute
                    { Type = unknown, Value = Asn1Any.FromValue("X", static (writer, value) => writer.WriteString(Asn1Tag.PrintableString, value, Asn1StringForm.Printable)) }
            }
        };
        const string expected = "CN=Doe\\, Jane\\+Jr+1.2.3.4=#130158,OU=\\ Root\\ ";
        Assert.Equal(expected, RdnSequenceFormatter.Format(bench));
        Assert.Equal(expected, RdnSequenceFormatter.Format(modern));

        var path = TestData.RepoPath("runtime-csharp/fixtures/cms/attached-signeddata.p7m");
        foreach (var args in new[] { new[] { "verify", path }, new[] { "verify", "--modern", path } })
        {
            var output = new StringWriter();
            Assert.Equal(0, CmsDemoCommand.Run(args, output, new StringWriter()));
            Assert.Contains("  Issuer: CN=Asn1Kit CMS Bench", output.ToString());
            Assert.Contains("  Subject: CN=Asn1Kit CMS Bench", output.ToString());
        }
    }

{
        var verifier = new RecordingVerifier();
        var results = CmsSignedDataInspector.Inspect(Fixture, verifier);
        Assert.Single(results);
        Assert.True(results[0].Accepted, results[0].Reason);
        Assert.Empty(verifier.Content);
        Assert.Empty(verifier.Digest);
        var info = ContentInfo.Decode(new Asn1Reader(Fixture, Asn1Encoding.Ber));
        Assert.Equal(RequireSignedData(info).EncapContentInfo.EContent!.Value.ToArray(), verifier.SignedBytes);
        Assert.NotEmpty(verifier.Signature);
    }

{
        var encoded = WithSignedAttrs();
        var verifier = new RecordingVerifier();
        var results = CmsSignedDataInspector.Inspect(encoded, verifier);
        Assert.True(results[0].Accepted, results[0].Reason);
        Assert.Equal(new byte[] { 0xAA }, verifier.Digest);
        Assert.Equal(0x31, verifier.SignedBytes[0]);

        var bench = Asn1Kit.Cms.ContentInfo.Decode(new Asn1Reader(encoded, Asn1Encoding.Ber));
        var retained = RequireSignedData(bench).SignerInfos[0].SignedAttrs!.Value.OriginalEncoding;
        Assert.False(retained.IsEmpty);
        Assert.Equal(new Asn1Any(retained).ContentsMemory.ToArray(), new Asn1Any(verifier.SignedBytes).ContentsMemory.ToArray());
    }

{
        var bench = Asn1Kit.Cms.ContentInfo.Decode(new Asn1Reader(Fixture, Asn1Encoding.Ber));
        var signedData = RequireSignedData(bench);
        var signerName = signedData.SignerInfos[0].Sid.IssuerAndSerialNumber!.Issuer.OriginalEncoding;
        var certName = signedData.Certificates!.Single(choice => choice.Certificate is not null)
            .Certificate!.Value.TbsCertificate.Value.Issuer.OriginalEncoding;
        Assert.False(signerName.IsEmpty);
        Assert.Equal(signerName.ToArray(), certName.ToArray());
    }

{
        Assert.Throws<Asn1Exception>(() => CmsSignedDataInspector.Inspect(new byte[] { 0x30, 0x02, 0x06 }, new RecordingVerifier()));
        Assert.Throws<Asn1Exception>(() => CmsSignedDataInspector.Inspect(Fixture.Concat(new byte[] { 0x00 }).ToArray(), new RecordingVerifier()));
    }

{
        var encoded = Mutate((_, signedData) =>
        {
            var keyIdentifier = new byte[] { 0xA1, 0xB2 };
            var certificate = signedData.Certificates!.Single(choice => choice.Certificate is not null).Certificate!.Value;
            SetSubjectKeyIdentifier(certificate, keyIdentifier);
            signedData.Certificates = new[]
            {
                CertificateChoices.FromCertificate(Asn1Lazy<Certificate>.FromValue(certificate))
            };
            GetSigner(signedData).Sid = SignerIdentifier.FromSubjectKeyIdentifier(keyIdentifier);
        });
        Assert.True(CmsSignedDataInspector.Inspect(encoded, new RecordingVerifier())[0].Accepted);
        AssertRejected(Mutate(encoded, (_, signedData) =>
            GetSigner(signedData).Sid = SignerIdentifier.FromSubjectKeyIdentifier(new byte[] { 0x01 })), "certificate");
    }

{
        var output = new StringWriter();
        var error = new StringWriter();
        Assert.Equal(0, CmsDemoCommand.Run(new[] { "verify", TestData.RepoPath("runtime-csharp/fixtures/cms/attached-signeddata.p7m") }, output, error));
        Assert.Contains("educational stub", output.ToString());
        Assert.Contains("no cryptographic verification", output.ToString());
        Assert.Equal(2, CmsDemoCommand.Run(Array.Empty<string>(), new StringWriter(), new StringWriter()));
        Assert.Equal(2, CmsDemoCommand.Run(new[] { "verify", "missing-file.p7m" }, new StringWriter(), new StringWriter()));
        Assert.Equal(2, CmsDemoCommand.Run(new[] { "unknown-command" }, new StringWriter(), new StringWriter()));

        var malformedPath = Path.GetTempFileName();
        try
        {
            File.WriteAllBytes(malformedPath, new byte[] { 0x00 });
            Assert.Equal(1, CmsDemoCommand.Run(new[] { "verify", malformedPath }, new StringWriter(), new StringWriter()));
        }
        finally
        {
            File.Delete(malformedPath);
        }
    }

{
        var info = Asn1Kit.Cms.ContentInfo.Decode(new Asn1Reader(Fixture, Asn1Encoding.Ber));
        var signedData = RequireSignedData(info);
        var certificate = signedData.Certificates!.Single(choice => choice.Certificate is not null).Certificate!.Value;
        Assert.False(certificate.TbsCertificate.OriginalEncoding.IsEmpty);
        Assert.False(certificate.TbsCertificate.Value.SubjectPublicKeyInfo.OriginalEncoding.IsEmpty);
        var rootEncoding = signedData.Certificates!.Single(choice => choice.Certificate is not null)
            .Certificate!.EncodedMemory;
        var rootPath = Path.GetTempFileName();
        var invalidCmsPath = Path.GetTempFileName();
        try
        {
            File.WriteAllBytes(rootPath, rootEncoding.ToArray());
            File.WriteAllBytes(invalidCmsPath, Mutate((_, sd) => GetSigner(sd).Signature = new byte[] { 1 }));
            var output = new StringWriter();
            Assert.Equal(0, CmsDemoCommand.Run(new[] { "verify", "--trusted-root", rootPath,
                TestData.RepoPath("runtime-csharp/fixtures/cms/attached-signeddata.p7m") }, output, new StringWriter()));
            Assert.Contains("RSA/SHA-256 verifier", output.ToString());
            Assert.Contains("Certificate chain", output.ToString());
            Assert.Equal(1, CmsDemoCommand.Run(new[] { "verify", "--trusted-root", rootPath, invalidCmsPath },
                new StringWriter(), new StringWriter()));

            certificate.Signature = Asn1BitString.CopyFrom(new byte[] { 1 }, 0);
            var invalidCertificateWriter = new Asn1Writer(Asn1Encoding.Der);
            certificate.Encode(invalidCertificateWriter);
            File.WriteAllBytes(rootPath, invalidCertificateWriter.Encode());
            signedData.Certificates = new[] { Asn1Kit.Cms.CertificateChoices.FromCertificate(
                Asn1Lazy<Asn1Kit.Pkix.Certificate>.FromValue(certificate)) };
            info.SetContent(ContentInfoContentBindings.SignedData, signedData);
            var invalidChainWriter = new Asn1Writer(Asn1Encoding.Der);
            info.Encode(invalidChainWriter);
            File.WriteAllBytes(invalidCmsPath, invalidChainWriter.Encode());
            var invalidChainOutput = new StringWriter();
            Assert.Equal(1, CmsDemoCommand.Run(new[] { "verify", "--trusted-root", rootPath, invalidCmsPath },
                invalidChainOutput, new StringWriter()));
            Assert.Contains("chain signature", invalidChainOutput.ToString());
        }
        finally { File.Delete(rootPath); File.Delete(invalidCmsPath); }
    }

{
        var info = Asn1Kit.Cms.ContentInfo.Decode(new Asn1Reader(Fixture, Asn1Encoding.Ber));
        var signedData = RequireSignedData(info);
        var root = signedData.Certificates!.Single(choice => choice.Certificate is not null).Certificate!.Value;
        var intermediate = CloneCertificate(root);
        intermediate.TbsCertificate.Value.Subject = BuildName("Intermediate");
        intermediate = CloneCertificate(intermediate);

        var leaf = CloneCertificate(root);
        leaf.TbsCertificate.Value.Subject = BuildName("Leaf");
        leaf.TbsCertificate.Value.Issuer = intermediate.TbsCertificate.Value.Subject.Value;
        signedData.Certificates = new[] { Asn1Kit.Cms.CertificateChoices.FromCertificate(Asn1Lazy<Asn1Kit.Pkix.Certificate>.FromValue(leaf)) };
        signedData.SignerInfos[0].Sid.IssuerAndSerialNumber!.Issuer = intermediate.TbsCertificate.Value.Subject.Value;
        info.SetContent(ContentInfoContentBindings.SignedData, signedData);
        var writer = new Asn1Writer(Asn1Encoding.Der);
        info.Encode(writer);
        var encoded = writer.Encode();

        var success = CmsSignedDataInspector.Inspect(encoded, new RecordingVerifier(),
            new[] { RetainCertificate(intermediate) }, new[] { RetainCertificate(root) });
        Assert.True(Assert.Single(success).Accepted, success[0].Reason);
        var failure = CmsSignedDataInspector.Inspect(encoded, new RecordingVerifier(),
            Array.Empty<Asn1Value<Asn1Kit.Pkix.Certificate>>(), new[] { RetainCertificate(root) });
        Assert.Contains("issuer is unavailable", Assert.Single(failure).Reason);
    }

{
        var info = Asn1Kit.Cms.ContentInfo.Decode(new Asn1Reader(Fixture, Asn1Encoding.Ber));
        var signedData = RequireSignedData(info);
        var root = signedData.Certificates!.Single(choice => choice.Certificate is not null).Certificate!.Value;
        var matching = CloneCertificate(root);
        matching.TbsCertificate.Value.Subject = BuildName("Intermediate");
        SetSubjectKeyIdentifier(matching, new byte[] { 0x11 });
        matching = CloneCertificate(matching);

        var other = CloneCertificate(root);
        other.TbsCertificate.Value.Subject = BuildName("Intermediate");
        SetSubjectKeyIdentifier(other, new byte[] { 0x22 });
        other = CloneCertificate(other);

        var leaf = CloneCertificate(root);
        leaf.TbsCertificate.Value.Subject = BuildName("Leaf");
        leaf.TbsCertificate.Value.Issuer = matching.TbsCertificate.Value.Subject.Value;
        SetAuthorityKeyIdentifier(leaf, new byte[] { 0x11 });
        signedData.Certificates = new[] { Asn1Kit.Cms.CertificateChoices.FromCertificate(
            Asn1Lazy<Asn1Kit.Pkix.Certificate>.FromValue(leaf)) };
        signedData.SignerInfos[0].Sid.IssuerAndSerialNumber!.Issuer = matching.TbsCertificate.Value.Subject.Value;
        info.SetContent(ContentInfoContentBindings.SignedData, signedData);
        var writer = new Asn1Writer(Asn1Encoding.Der);
        info.Encode(writer);
        var encoded = writer.Encode();

        var benchAvailable = new[] { RetainCertificate(other), RetainCertificate(matching) };
        var benchRoot = new[] { RetainCertificate(root) };
        var benchResult = CmsSignedDataInspector.Inspect(encoded, new RecordingVerifier(), benchAvailable, benchRoot);
        Assert.True(Assert.Single(benchResult).Accepted, benchResult[0].Reason);

        var modernAvailable = benchAvailable.Select(item => RetainModernCertificate(item.OriginalEncoding)).ToArray();
        var modernRoot = new[] { RetainModernCertificate(benchRoot[0].OriginalEncoding) };
        var modernResult = CmsModernSignedDataInspector.Inspect(encoded, new ModernRecordingVerifier(), modernAvailable, modernRoot);
        Assert.True(Assert.Single(modernResult).Accepted, modernResult[0].Reason);

        SetAuthorityKeyIdentifier(leaf, new byte[] { 0x33 });
        signedData.Certificates = new[] { Asn1Kit.Cms.CertificateChoices.FromCertificate(
            Asn1Lazy<Asn1Kit.Pkix.Certificate>.FromValue(leaf)) };
        info.SetContent(ContentInfoContentBindings.SignedData, signedData);
        writer = new Asn1Writer(Asn1Encoding.Der);
        info.Encode(writer);
        encoded = writer.Encode();
        Assert.Contains("issuer is unavailable", Assert.Single(CmsSignedDataInspector.Inspect(
            encoded, new RecordingVerifier(), benchAvailable, benchRoot)).Reason);
        Assert.Contains("issuer is unavailable", Assert.Single(CmsModernSignedDataInspector.Inspect(
            encoded, new ModernRecordingVerifier(), modernAvailable, modernRoot)).Reason);

        matching.TbsCertificate.Value.SerialNumber = Asn1Integer.FromInt32(101);
        other.TbsCertificate.Value.SerialNumber = Asn1Integer.FromInt32(202);
        benchAvailable = new[] { RetainCertificate(other), RetainCertificate(matching) };
        modernAvailable = benchAvailable.Select(item => RetainModernCertificate(item.OriginalEncoding)).ToArray();
        SetAuthorityKeyIdentifier(leaf, new Asn1Kit.Pkix.AuthorityKeyIdentifier
        {
            AuthorityCertIssuer = new[] { Asn1Kit.Pkix.GeneralName.FromDirectoryName(
                matching.TbsCertificate.Value.Issuer.Value) },
            AuthorityCertSerialNumber = matching.TbsCertificate.Value.SerialNumber
        });
        signedData.Certificates = new[] { Asn1Kit.Cms.CertificateChoices.FromCertificate(
            Asn1Lazy<Asn1Kit.Pkix.Certificate>.FromValue(leaf)) };
        info.SetContent(ContentInfoContentBindings.SignedData, signedData);
        writer = new Asn1Writer(Asn1Encoding.Der);
        info.Encode(writer);
        encoded = writer.Encode();
        benchResult = CmsSignedDataInspector.Inspect(encoded, new RecordingVerifier(), benchAvailable, benchRoot);
        Assert.True(Assert.Single(benchResult).Accepted, benchResult[0].Reason);
        modernResult = CmsModernSignedDataInspector.Inspect(encoded, new ModernRecordingVerifier(), modernAvailable, modernRoot);
        Assert.True(Assert.Single(modernResult).Accepted, modernResult[0].Reason);

        SetAuthorityKeyIdentifier(leaf, new Asn1Kit.Pkix.AuthorityKeyIdentifier
        {
            AuthorityCertIssuer = new[] { Asn1Kit.Pkix.GeneralName.FromDirectoryName(
                matching.TbsCertificate.Value.Issuer.Value) },
            AuthorityCertSerialNumber = Asn1Integer.FromInt32(303)
        });
        signedData.Certificates = new[] { Asn1Kit.Cms.CertificateChoices.FromCertificate(
            Asn1Lazy<Asn1Kit.Pkix.Certificate>.FromValue(leaf)) };
        info.SetContent(ContentInfoContentBindings.SignedData, signedData);
        writer = new Asn1Writer(Asn1Encoding.Der);
        info.Encode(writer);
        encoded = writer.Encode();
        Assert.Contains("issuer is unavailable", Assert.Single(CmsSignedDataInspector.Inspect(
            encoded, new RecordingVerifier(), benchAvailable, benchRoot)).Reason);
        Assert.Contains("issuer is unavailable", Assert.Single(CmsModernSignedDataInspector.Inspect(
            encoded, new ModernRecordingVerifier(), modernAvailable, modernRoot)).Reason);
    }

{
        var certPath = TestData.RepoPath("runtime-csharp/fixtures/pkix/GoodCACert.crt");
        foreach (var args in new[] { new[] { "print-cert", certPath }, new[] { "print-cert", "--modern", certPath } })
        {
            var output = new StringWriter();
            Assert.Equal(0, CmsDemoCommand.Run(args, output, new StringWriter()));
            var text = output.ToString();
            Assert.Contains("Certificate:", text);
            Assert.Contains("Serial Number:", text);
            Assert.Contains("Issuer:", text);
            Assert.Contains("Subject:", text);
            Assert.Contains("Validity", text);
            Assert.Contains("Not Before:", text);
            Assert.Contains("Not After :", text);
        }
    }

{
        var cmsPath = TestData.RepoPath("runtime-csharp/fixtures/cms/attached-signeddata.p7m");
        foreach (var args in new[] { new[] { "print-cms", cmsPath }, new[] { "print-cms", "--modern", cmsPath } })
        {
            var output = new StringWriter();
            Assert.Equal(0, CmsDemoCommand.Run(args, output, new StringWriter()));
            var text = output.ToString();
            Assert.Contains("CMS_ContentInfo:", text);
            Assert.Contains("d.signedData:", text);
            Assert.Contains("encapContentInfo:", text);
            Assert.Contains("signerInfos:", text);
        }

        var malformedPath = Path.GetTempFileName();
        try
        {
            File.WriteAllBytes(malformedPath, new byte[] { 0x00 });
            Assert.Equal(1, CmsDemoCommand.Run(new[] { "print-cms", malformedPath }, new StringWriter(), new StringWriter()));
        }
        finally
        {
            File.Delete(malformedPath);
        }
    }

{
        var info = ContentInfo.Decode(new Asn1Reader(Fixture, Asn1Encoding.Ber));
        var signedData = RequireSignedData(info);
        var certificateEncoding = signedData.Certificates!.Single(choice => choice.Certificate is not null)
            .Certificate!.EncodedMemory.ToArray();
        var contentPath = Path.GetTempFileName();
        var certPath = Path.GetTempFileName();
        var outputPath = Path.GetTempFileName();
        var modernOutputPath = Path.GetTempFileName();
        try
        {
            File.WriteAllBytes(contentPath, new byte[] { 0x68, 0x65, 0x6C, 0x6C, 0x6F });
            File.WriteAllBytes(certPath, certificateEncoding);

            var signOutput = new StringWriter();
            Assert.Equal(0, CmsDemoCommand.Run(new[]
            {
                "sign", "--certificate", certPath, "--content", contentPath, "--output", outputPath
            }, signOutput, new StringWriter()));
            Assert.Contains("placeholder signature", signOutput.ToString());
            Assert.Contains("Issuer: CN=Asn1Kit CMS Bench", signOutput.ToString());

            var verifyOutput = new StringWriter();
            Assert.Equal(0, CmsDemoCommand.Run(new[] { "verify", outputPath }, verifyOutput, new StringWriter()));
            Assert.Contains("educational stub", verifyOutput.ToString());

            var printOutput = new StringWriter();
            Assert.Equal(0, CmsDemoCommand.Run(new[] { "print-cms", outputPath }, printOutput, new StringWriter()));
            Assert.Contains("signedAttrs:", printOutput.ToString());
            Assert.Contains("Certificate:", printOutput.ToString());

            Assert.Equal(0, CmsDemoCommand.Run(new[]
            {
                "sign", "--modern", "--certificate", certPath, "--content", contentPath, "--output", modernOutputPath
            }, new StringWriter(), new StringWriter()));
            Assert.Equal(0, CmsDemoCommand.Run(new[] { "verify", "--modern", modernOutputPath },
                new StringWriter(), new StringWriter()));
            var modernPrint = new StringWriter();
            Assert.Equal(0, CmsDemoCommand.Run(new[] { "print-cms", "--modern", modernOutputPath },
                modernPrint, new StringWriter()));
            Assert.Contains("signedAttrs:", modernPrint.ToString());
        }
        finally
        {
            File.Delete(contentPath);
            File.Delete(certPath);
            File.Delete(outputPath);
            File.Delete(modernOutputPath);
        }
    }

