        var outer = reader.EnterSequence(Asn1Tag.Sequence);
        var inner = reader.EnterSequence(Asn1Tag.Sequence);

        var threw = false;
        try
        {
            outer.Dispose();
        }
        catch (InvalidOperationException)
        {
            threw = true;
        }

        Assert.True(threw);
        Assert.Equal(1, reader.ReadInt32(Asn1Tag.Integer));
        inner.Dispose();
        outer.Dispose();
        Assert.True(reader.Eof);
    }

