{
        var ber = Hex.Parse("24800403416E6E0000");
        var us = new Asn1Reader(ber, Asn1Encoding.Ber).ReadOctetString(Asn1Tag.OctetString);
        var bcl = DotnetAsnOracle.DecodeOctetString(ber, AsnEncodingRules.BER);
        Assert.Equal(bcl, us.ToArray());
        Assert.Equal(new byte[] { 0x41, 0x6E, 0x6E }, us.ToArray());
    }

{
        var us = EncodeUs(w =>
        {
            using (w.EnterSetOf(Asn1Tag.Set))
            {
                w.WriteInteger(Asn1Tag.Integer, 2);
                w.WriteInteger(Asn1Tag.Integer, 1);
            }
        });

        var bclWriter = new AsnWriter(AsnEncodingRules.DER);
        bclWriter.PushSetOf();
        bclWriter.WriteInteger(2);
        bclWriter.WriteInteger(1);
        bclWriter.PopSetOf();
        var bcl = bclWriter.Encode();

        Assert.Equal(Hex.Format(bcl), Hex.Format(us));
    }

{
        var us = EncodeUs(w =>
        {
            using (w.EnterSequence(Asn1Tag.Sequence))
            {
                w.WriteInteger(Asn1Tag.Integer, 1);
                w.WriteInteger(Asn1Tag.Integer, 2);
            }
        });

        var bclWriter = new AsnWriter(AsnEncodingRules.DER);
        bclWriter.PushSequence();
        bclWriter.WriteInteger(1);
        bclWriter.WriteInteger(2);
        bclWriter.PopSequence();
        var bcl = bclWriter.Encode();

        Assert.Equal(Hex.Format(bcl), Hex.Format(us));

        var reader = new Asn1Reader(bcl, Asn1Encoding.Der);
        using (reader.EnterSequence(Asn1Tag.Sequence))
        {
            Assert.Equal(1, reader.ReadInteger(Asn1Tag.Integer));
            Assert.Equal(2, reader.ReadInteger(Asn1Tag.Integer));
        }
    }

{
        var writer = new Asn1Writer(Asn1Encoding.Der);
        using (writer.EnterSequence(Asn1Tag.Sequence))
        {
            Asn1Integer.Encode(writer, 42, new Asn1Tag(Asn1TagClass.ContextSpecific, 0));
            Asn1OctetString.Encode(writer, Encoding.UTF8.GetBytes("Ann"), new Asn1Tag(Asn1TagClass.ContextSpecific, 1));
        }
        var bytes = writer.Encode();
        var reader = new Asn1Reader(bytes, Asn1Encoding.Der);
        using (reader.EnterSequence(Asn1Tag.Sequence))
        {
            Assert.Equal(42, Asn1Integer.Decode(reader, new Asn1Tag(Asn1TagClass.ContextSpecific, 0)).GetInt32());
            Assert.Equal("Ann", Encoding.UTF8.GetString(Asn1OctetString.Decode(reader, new Asn1Tag(Asn1TagClass.ContextSpecific, 1)).Span));
            Assert.True(reader.Eof);
        }
    }

{
        var writer = new Asn1Writer(Asn1Encoding.Der);
        using (writer.EnterSequence(Asn1Tag.Sequence)) { }
        Assert.Equal(new byte[] { 0x30, 0x00 }, writer.Encode());
    }

{
        // 128-byte OCTET STRING: 04 81 80 + 128 payload = 131 content octets → outer length long-form.
        var payload = new byte[128];
        for (var i = 0; i < payload.Length; i++)
        {
            payload[i] = (byte)i;
        }

        var writer = new Asn1Writer(Asn1Encoding.Der);
        using (writer.EnterSequence(Asn1Tag.Sequence))
        {
            writer.WriteOctetString(Asn1Tag.OctetString, payload);
        }
        var bytes = writer.Encode();

        Assert.Equal(0x30, bytes[0]);
        Assert.Equal(0x81, bytes[1]);
        Assert.Equal(131, bytes[2]);
        Assert.Equal(0x04, bytes[3]);
        Assert.Equal(0x81, bytes[4]);
        Assert.Equal(0x80, bytes[5]);
        Assert.Equal(payload, bytes.AsSpan(6).ToArray());

        var reader = new Asn1Reader(bytes, Asn1Encoding.Der);
        using (reader.EnterSequence(Asn1Tag.Sequence))
        {
            Assert.Equal(payload, reader.ReadOctetString(Asn1Tag.OctetString).ToArray());
            Assert.True(reader.Eof);
        }
    }

{
        var tag = new Asn1Tag(Asn1TagClass.ContextSpecific, 201);
        var writer = new Asn1Writer(Asn1Encoding.Der);
        writer.WriteInteger(tag, 1);

        Assert.Equal(new byte[] { 0x9F, 0x81, 0x49, 0x01, 0x01 }, writer.Encode());

        var reader = new Asn1Reader(writer.Encode(), Asn1Encoding.Der);
        Assert.Equal(1, reader.ReadInt32(tag));
        Assert.True(reader.Eof);
    }

{
        var writer = new Asn1Writer(Asn1Encoding.Der);
        using (writer.EnterSequence(Asn1Tag.Sequence))
        {
            using (writer.EnterSequence(Asn1Tag.Sequence))
            {
                using (writer.EnterSequence(Asn1Tag.Sequence))
                {
                    Asn1Integer.Encode(writer, 7);
                    Asn1Integer.Encode(writer, 9);
                }
            }
        }
        var bytes = writer.Encode();

        // 30 0A 30 08 30 06 02 01 07 02 01 09
        Assert.Equal(
            new byte[] { 0x30, 0x0A, 0x30, 0x08, 0x30, 0x06, 0x02, 0x01, 0x07, 0x02, 0x01, 0x09 },
            bytes);

        var reader = new Asn1Reader(bytes, Asn1Encoding.Der);
        using (reader.EnterSequence(Asn1Tag.Sequence))
        {
            using (reader.EnterSequence(Asn1Tag.Sequence))
            {
                using (reader.EnterSequence(Asn1Tag.Sequence))
                {
                    Assert.Equal(7, Asn1Integer.Decode(reader).GetInt32());
                    Assert.Equal(9, Asn1Integer.Decode(reader).GetInt32());
                    Assert.True(reader.Eof);
                }

                Assert.True(reader.Eof);
            }

            Assert.True(reader.Eof);
        }
    }

{
        var writer = new Asn1Writer(Asn1Encoding.Der);
        var outer = writer.EnterSequence(Asn1Tag.Sequence);
        var outerCopy = outer;
        var inner = writer.EnterExplicit(new Asn1Tag(Asn1TagClass.ContextSpecific, 0, constructed: true));

        InvalidOperationException? outOfOrder = null;
        try
        {
            outer.Dispose();
        }
        catch (InvalidOperationException exception)
        {
            outOfOrder = exception;
        }

        Assert.NotNull(outOfOrder);
        Assert.Contains("LIFO", outOfOrder!.Message);

        inner.Dispose();
        outer.Dispose();

        InvalidOperationException? copiedDispose = null;
        try
        {
            outerCopy.Dispose();
        }
        catch (InvalidOperationException exception)
        {
            copiedDispose = exception;
        }

        Assert.NotNull(copiedDispose);
        Assert.Contains("disposed once", copiedDispose!.Message);
        InvalidOperationException? repeatedDispose = null;
        try
        {
            outer.Dispose();
        }
        catch (InvalidOperationException exception)
        {
            repeatedDispose = exception;
        }

        Assert.NotNull(repeatedDispose);
        Assert.Contains("disposed once", repeatedDispose!.Message);
        Assert.Equal(Hex.Parse("3002A000"), writer.Encode());
    }

{
        var writer = new Asn1Writer(Asn1Encoding.Der);
        using (writer.EnterSequence(Asn1Tag.Sequence))
        {
            writer.WriteNull(Asn1Tag.Null);
            Assert.Throws<InvalidOperationException>(() => writer.Encode());
            Assert.Throws<InvalidOperationException>(() => writer.Encode(static encoded => encoded.Length));
            Assert.Throws<InvalidOperationException>(() => writer.Encode(static encoded => { }));
            Assert.Throws<InvalidOperationException>(() => writer.TryEncode(new byte[16], out _));
            Assert.Throws<InvalidOperationException>(() => writer.Reset());
        }

        Assert.Equal(Hex.Parse("30020500"), writer.Encode());
    }

{
        var writer = new Asn1Writer(Asn1Encoding.Der);
        InvalidOperationException? thrown = null;
        try
        {
            using (writer.EnterSequence(Asn1Tag.Sequence))
            {
                writer.WriteInteger(Asn1Tag.Integer, 1);
                throw new InvalidOperationException("boom");
            }
        }
        catch (InvalidOperationException exception)
        {
            thrown = exception;
        }

        Assert.NotNull(thrown);
        Assert.Equal("boom", thrown!.Message);
        Assert.Equal(Hex.Parse("3003020101"), writer.Encode());
        writer.Reset();
        writer.WriteNull(Asn1Tag.Null);
        Assert.Equal(Hex.Parse("0500"), writer.Encode());
    }

{
