        var decodedCalls = 0;
        var reader = new Asn1Reader(bytes, Asn1Encoding.Der);
        var lazy = reader.ReadLazy(r =>
        {
            decodedCalls++;
            using (r.EnterSequence(Asn1Tag.Sequence))
            {
